# Let's try to find a partition of {1, ..., 13} into 3 sets without Schur triples.
def solve_schur(m, n):
    # m sets, elements 1 to n
    partition = [0] * (n + 1)

    def is_valid(val, color):
        # Check if adding val to color set creates a Schur triple
        # x + y = val where x, y are already in the set
        # val + x = y where x is already in the set
        # val + val = y where y is already in the set
        # val + val = val (only if val=0, but val >= 1)
        for x in range(1, val):
            if partition[x] == color:
                # Case 1: x + y = val
                if partition[val - x] == color:
                    return False
        for x in range(1, n + 1):
            if partition[x] == color:
                # Case 2: val + x = y
                if val + x <= n and partition[val + x] == color:
                    return False
        # Case 3: val + val = y
        if 2 * val <= n and partition[2 * val] == color:
            return False
        return True

    def backtrack(val):
        if val > n:
            return True
        for color in range(1, m + 1):
            if is_valid(val, color):
                partition[val] = color
                if backtrack(val + 1):
                    return True
                partition[val] = 0
        return False

    if backtrack(1):
        return partition[1:]
    return None

print("S(3) partition of 13:", solve_schur(3, 13))
print("S(3) partition of 14:", solve_schur(3, 14))
print("S(4) partition of 40:", solve_schur(4, 40))
